_V7_BOOK_RAW = None


def _load_v7_book_raw():
    global _V7_BOOK_RAW

    if _V7_BOOK_RAW is None:
        compressed = base64.b85decode(
            V7_BOOK_DATA_B85.encode(
                "ascii"
            )
        )

        _V7_BOOK_RAW = lzma.decompress(
            compressed
        )

    return _V7_BOOK_RAW


# ============================================================
# V7 BOOK READER
# ============================================================

import bisect
import struct
from pathlib import Path


BLOCK_SIZE = 512

MAGIC = b"C4V7"
VERSION = 1

HEADER = struct.Struct("<4sBII")
BLOCK_RECORD = struct.Struct("<QI")



def mirror_bitboard(position):
    mirrored = 0
    column_mask = (1 << 7) - 1

    for col in range(7):
        column = (
            position >> (col * 7)
        ) & column_mask

        mirrored |= (
            column
            << ((6 - col) * 7)
        )

    return mirrored


def canonical_key(
    current,
    mask,
):
    key = current + mask

    mirrored_current = (
        mirror_bitboard(current)
    )

    mirrored_mask = (
        mirror_bitboard(mask)
    )

    mirrored_key = (
        mirrored_current
        + mirrored_mask
    )

    return min(
        key,
        mirrored_key,
    )


def read_varint(
    data,
    position,
):
    value = 0
    shift = 0

    while True:
        byte = data[position]
        position += 1

        value |= (
            (byte & 0x7F)
            << shift
        )

        if byte < 0x80:
            return value, position

        shift += 7


class V7OpeningBook:
    def __init__(
        self,
        path=None,
    ):
        self.path = Path(path)

        self.data = (
            self.path.read_bytes()
        )

        (
            magic,
            version,
            self.count,
            self.block_count,
        ) = HEADER.unpack_from(
            self.data,
            0,
        )

        if magic != MAGIC:
            raise ValueError(
                "Invalid V7 opening book"
            )

        if version != VERSION:
            raise ValueError(
                f"Unsupported V7 book "
                f"version: {version}"
            )

        index_start = HEADER.size

        self.payload_start = (
            index_start
            + self.block_count
            * BLOCK_RECORD.size
        )

        self.block_keys = []
        self.block_offsets = []

        for index in range(
            self.block_count
        ):
            key, offset = (
                BLOCK_RECORD.unpack_from(
                    self.data,
                    index_start
                    + index
                    * BLOCK_RECORD.size,
                )
            )

            self.block_keys.append(
                key
            )

            self.block_offsets.append(
                offset
            )

        self.payload = memoryview(
            self.data
        )[self.payload_start:]

    def lookup_key(
        self,
        target,
    ):
        block = (
            bisect.bisect_right(
                self.block_keys,
                target,
            )
            - 1
        )

        if block < 0:
            return None

        key = self.block_keys[block]

        position = (
            self.block_offsets[block]
        )

        score = self.payload[
            position
        ]

        position += 1

        if key == target:
            return (
                score
                if score < 128
                else score - 256
            )

        first_index = (
            block * BLOCK_SIZE
        )

        entries = min(
            BLOCK_SIZE,
            self.count - first_index,
        )

        for _ in range(
            1,
            entries,
        ):
            delta, position = (
                read_varint(
                    self.payload,
                    position,
                )
            )

            key += delta

            score = self.payload[
                position
            ]

            position += 1

            if key == target:
                return (
                    score
                    if score < 128
                    else score - 256
                )

            if key > target:
                return None

        return None

    def lookup(
        self,
        p1,
        p2,
        player,
    ):
        mask = p1 | p2

        current = (
            p1
            if player == 1
            else p2
        )

        key = canonical_key(
            current,
            mask,
        )

        return self.lookup_key(
            key
        )

    def __len__(self):
        return self.count


class EmbeddedV7OpeningBook(
    V7OpeningBook
):
    """
    V7OpeningBook backed entirely by the
    book embedded in this submission.
    """

    def __init__(self):
        self.path = None

        self.data = (
            _load_v7_book_raw()
        )

        (
            magic,
            version,
            self.count,
            self.block_count,
        ) = HEADER.unpack_from(
            self.data,
            0,
        )

        if magic != MAGIC:
            raise ValueError(
                "Invalid embedded V7 book"
            )

        if version != VERSION:
            raise ValueError(
                "Unsupported embedded V7 book"
            )

        index_start = HEADER.size

        self.payload_start = (
            index_start
            + self.block_count
            * BLOCK_RECORD.size
        )

        self.block_keys = []
        self.block_offsets = []

        for index in range(
            self.block_count
        ):
            key, offset = (
                BLOCK_RECORD.unpack_from(
                    self.data,
                    index_start
                    + index
                    * BLOCK_RECORD.size,
                )
            )

            self.block_keys.append(
                key
            )

            self.block_offsets.append(
                offset
            )

        self.payload = memoryview(
            self.data
        )[self.payload_start:]


V7_BOOK = EmbeddedV7OpeningBook()


def v71_exact_book_move(
    p1,
    p2,
    player,
):
    """
    Return an exactly proven optimal move
    when the V7 book contains the parent
    and every required non-terminal child.

    Otherwise return None and allow V6.1
    to handle the position.
    """

    parent_score = V7_BOOK.lookup(
        p1,
        p2,
        player,
    )

    if parent_score is None:
        return None

    legal = valid_moves(
        p1,
        p2,
    )

    if not legal:
        return None

    ply = (
        p1 | p2
    ).bit_count()

    scored = []

    for col in legal:
        n1, n2 = play_move(
            p1,
            p2,
            col,
            player,
        )

        own_position = (
            n1
            if player == 1
            else n2
        )

        # Immediate winning move.
        if has_won(
            own_position
        ):
            score = (
                42
                - ply
                + 1
            ) // 2

            scored.append(
                (
                    col,
                    score,
                )
            )

            continue

        child_score = V7_BOOK.lookup(
            n1,
            n2,
            3 - player,
        )

        # Never override V6.1 unless the
        # whole decision is exactly proven.
        if child_score is None:
            return None

        scored.append(
            (
                col,
                -int(child_score),
            )
        )

    if not scored:
        return None

    best_score = max(
        score
        for _, score in scored
    )

    # Safety check against the exact parent.
    if best_score != int(
        parent_score
    ):
        return None

    best_moves = {
        col
        for col, score in scored
        if score == best_score
    }

    for col in CENTER_ORDER:
        if col in best_moves:
            return col

    return None


# ============================================================
# V6B SEARCH SETTINGS
# ============================================================

SEARCH_TIME = 1.65

# Exact endgame gets its own smaller budget.
# If exact search times out, choose_move_exact()
# returns a safe fallback rather than launching
# another full search.
EXACT_TIME = 1.40

# At 23 or fewer empty cells, attempt a direct
# terminal-depth solve.
EXACT_ENDGAME_EMPTIES = 23


# ============================================================
# KAGGLE AGENT
# ============================================================

def agent(
    observation,
    configuration,
):
    p1, p2 = board_to_bitboards(
        observation.board
    )

    player = observation.mark

    # --------------------------------------------------------
    # 1. V7.1 EXACT DEPTH-12 OVERRIDE
    # --------------------------------------------------------

    v71_move = v71_exact_book_move(
        p1,
        p2,
        player,
    )

    if v71_move is not None:
        return int(
            v71_move
        )

    # --------------------------------------------------------
    # 2. V6.1 SOLVED OPENING BOOK
    # --------------------------------------------------------

    book_move = book_choose_move(
        p1,
        p2,
    )

    if book_move is not None:
        return int(
            book_move
        )

    # --------------------------------------------------------
    # 3. EXACT ENDGAME
    # --------------------------------------------------------

    ply = (
        p1 | p2
    ).bit_count()

    empties = 42 - ply

    if (
        empties
        <= EXACT_ENDGAME_EMPTIES
    ):
        engine = SearchEngine(
            time_limit=EXACT_TIME
        )

        move = (
            engine.choose_move_exact(
                p1,
                p2,
                player,
                depth=empties,
            )
        )

        # choose_move_exact() returns a safe fallback
        # if the terminal search exceeds its budget.
        #
        # None should therefore occur only when there
        # is no legal move.
        if move is not None:
            return int(
                move
            )

    # --------------------------------------------------------
    # 4. TIMED MIDDLEGAME SEARCH
    # --------------------------------------------------------

    engine = SearchEngine(
        time_limit=SEARCH_TIME
    )

    move = engine.choose_move(
        p1,
        p2,
        player,
    )

    return int(
        move
    )
